import{St as e,at as t,it as n,n as r,st as i,vt as a}from"./chunks/framework.yntlMcNk.js";var o=JSON.parse(`{"title":"Catalogs","description":"","frontmatter":{"title":"Catalogs","covers":{"screens":["SCR-020","SCR-028"],"stories":["US-046","US-047","US-048","US-049","US-050"]}},"headers":[],"relativePath":"usage/catalogs.md","filePath":"usage/catalogs.md"}`),s={name:`usage/catalogs.md`};function c(r,o,s,c,l,u){let d=e(`Screenshot`);return a(),n(`div`,null,[o[0]||=t(`<h1 id="catalogs" tabindex="-1">Catalogs <a class="header-anchor" href="#catalogs" aria-label="Permalink to “Catalogs”">​</a></h1><p>A catalog is a reusable table view of the repository. It shows the entities of one entity type as rows. You need the permission <code>entity:read</code> (for example the role <code>viewer</code>) to see catalogs and create personal ones; shared catalogs need <code>catalog:manage</code> (role <code>enterprise-architect</code>).</p><h2 id="create-a-catalog" tabindex="-1">Create a catalog <a class="header-anchor" href="#create-a-catalog" aria-label="Permalink to “Create a catalog”">​</a></h2><ol><li><p>Choose <em>Catalogs</em> in the header, then <em>New catalog</em>.</p></li><li><p>Fill in the dialog <em>New catalog</em>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>Name</td><td>required; unique within the instance, regardless of upper and lower case</td></tr><tr><td>Description</td><td>optional, up to 1000 characters</td></tr><tr><td>Primary entity type</td><td>required; its entities become the rows of the table</td></tr><tr><td>Visibility</td><td><em>Shared</em>: visible to all users of the instance (needs the permission to manage catalogs); <em>Personal</em>: visible only to you</td></tr><tr><td>Default join mode</td><td><em>Aggregate</em>: one row per entity, linked entities in one cell; <em>Rows</em>: one row per linked entity. Applies to joins added later</td></tr></tbody></table></li></ol>`,4),i(d,{name:`catalog-create`,alt:`Dialog New catalog with name, description, entity type and visibility`}),o[1]||=t(`<ol start="3"><li>Choose <em>Create catalog</em>. The new catalog opens.</li></ol><p>If the name is already taken, the dialog says so; choose another name. Without the permission to manage catalogs, <em>Shared</em> is not selectable.</p><h2 id="browse-a-catalog" tabindex="-1">Browse a catalog <a class="header-anchor" href="#browse-a-catalog" aria-label="Permalink to “Browse a catalog”">​</a></h2><p>The list <em>Catalogs</em> shows every catalog you may see, marked <em>Shared</em> or <em>Personal</em>. Open one to see its table:</p>`,4),i(d,{name:`catalogs`,alt:`List of catalogs`}),i(d,{name:`catalog-table`,alt:`Table of a catalog with application components`}),o[2]||=t(`<ul><li>Names of entity types, column headers and values of enum properties appear in your language where your organization has translated them (see <a href="./login#your-profile">Your profile</a>).</li><li>As long as no columns are configured (see <a href="#configure-columns">Configure columns</a>), the table shows the columns <em>Name</em> and – if the entity type has the property <em>Status</em> – <em>Status</em>.</li><li>Values of an enum property, such as <em>Status</em>, are sorted in the order of the values, not alphabetically; entries without a value come last.</li><li>Click a column header to sort: ascending, descending, and back to the default order.</li><li>The table shows 50 entries per page; use the pagination below the table to move between pages.</li><li>Sort and page are part of the address of the page. Back navigation, a reload or a shared link restore the same view; invalid values in the address are ignored and the first page is shown in the default order.</li><li>If the entity type has no entities yet, the table shows <em>No entries found</em>.</li><li>Another person&#39;s personal catalog cannot be opened; it behaves like a catalog that does not exist (<em>Catalog not found</em>).</li></ul><p>Through the API, <code>GET /catalogs/{id}/query</code> returns the same rows with the parameters <code>page</code> (from 0), <code>pageSize</code> (1–200, default 50) and <code>sort</code> (<code>{field}:{asc|desc}</code>).</p><h2 id="configure-columns" tabindex="-1">Configure columns <a class="header-anchor" href="#configure-columns" aria-label="Permalink to “Configure columns”">​</a></h2><p>You decide which attributes a catalog shows, in which order and under which header. A shared catalog needs the permission to manage catalogs (<code>catalog:manage</code>, role <code>enterprise-architect</code>); your own personal catalog you configure yourself.</p><ol><li>Open the catalog and choose <em>Configure columns</em>.</li><li>The dialog lists every attribute of the entity type: the fields <em>Name</em>, <em>Description</em>, <em>External ID</em>, <em>Created</em>, <em>Updated</em> and <em>Version</em>, and every property assigned to the entity type, also the inherited ones.</li><li>Per row: <ul><li><em>Visible</em> shows or hides the column. A hidden column stays in the list, so you can show it again later.</li><li><em>Header</em> replaces the name of the attribute in the table, for example <em>Operational Status</em> for <em>Status</em>.</li><li><em>Sortable</em> decides whether readers may sort by the column.</li></ul></li><li>Change the order by dragging a row, or with the arrow buttons of a row.</li><li>Under <em>Default sort</em>, choose the column and direction the table is sorted by when nobody chose a sort.</li><li>Choose <em>Save</em>. At least one column must be visible.</li></ol><p>A property that is no longer assigned to the entity type shows as <em>Not available</em> and is removed when you save. Every change is recorded in the audit trail.</p><p>Through the API, <code>PUT /catalogs/{id}/columns</code> replaces the list. Each column names a field (<code>&quot;field&quot;: &quot;name&quot;</code>, <code>description</code>, <code>externalId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>entityVersion</code>) or a property (<code>&quot;propertyDefId&quot;: &quot;…&quot;</code>), with <code>displayLabel</code>, <code>visible</code>, <code>sortable</code> and at most one <code>defaultSortDirection</code> (<code>asc</code> or <code>desc</code>). An empty list restores the default columns.</p><h2 id="joins" tabindex="-1">Joins <a class="header-anchor" href="#joins" aria-label="Permalink to “Joins”">​</a></h2><p>A join shows related entities next to each entry of the catalog, for example all interfaces of an application. It follows a connection type of the metamodel, such as <em>Data Flow</em>. Joins are configured like columns: a shared catalog needs the permission to manage catalogs, your own personal catalog you configure yourself.</p><ol><li>Open the catalog and choose <em>Joins</em>. The dialog lists the joins of the catalog.</li><li>Choose <em>Add join</em> and go through the four steps: <ol><li><em>Connection type</em>: only connection types that connect the entity type of the catalog are offered.</li><li><em>Direction</em>: <em>Outgoing</em> follows connections that start at the entry, <em>Incoming</em> those that end at it, <em>Both directions</em> both; an entity reached in both directions is listed once.</li><li><em>Target type</em>: only entity types the connection type allows at its other end.</li><li><em>Name</em>, <em>Default mode</em> and the columns of the target type, chosen like in <a href="#configure-columns">Configure columns</a>. The name becomes the header above the columns of the join.</li></ol></li><li>Choose <em>Save</em>. The table shows the join as a group of columns.</li></ol><p><em>Edit</em> changes a join, <em>Remove</em> removes it. A join whose connection type or target type no longer exists or no longer connects the entity types shows as <em>Not available</em> and is left out of the table. A catalog has at most 10 joins. Every change is recorded in the audit trail.</p><h3 id="compact-or-rows" tabindex="-1">Compact or rows <a class="header-anchor" href="#compact-or-rows" aria-label="Permalink to “Compact or rows”">​</a></h3><p>Every join has the switch <em>Compact / Rows</em> in its header:</p><ul><li><em>Compact</em> shows one row per entry; a cell lists all linked entities, one per line. An entry without linked entities keeps its row with an empty cell.</li><li><em>Rows</em> shows one row per linked entity; the entry repeats. In this mode you can also sort by a column of the join, and the page counts rows.</li></ul><p>The switch changes only your view, not the catalog. It is part of the address of the page, like sort and page. With several joins in <em>Rows</em>, each combination of their linked entities gets a row of its own. The <em>Default mode</em> of a join, or else the default join mode of the catalog, applies when you open the catalog.</p><p>Through the API, <code>POST /catalogs/{id}/joins</code> adds a join with <code>name</code>, <code>connectionMetatypeId</code>, <code>joinDirection</code> (<code>outbound</code>, <code>inbound</code>, <code>both</code>), <code>targetMetatypeId</code>, <code>targetColumns</code> (like the columns, without default sort) and <code>defaultJoinMode</code> (<code>rows</code>, <code>aggregate</code> or <code>null</code>). <code>PUT</code> and <code>DELETE /catalogs/{id}/joins/{joinId}</code> change and remove it. The query returns the results of every join in <code>joinResults</code> under the ID of the join; <code>joinMode[{joinId}]=rows</code> switches a join for one query, and <code>sort={joinId}.{key}:asc</code> sorts by a join column in rows mode.</p>`,16)])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};